//FUNZIONE CHE RESTITUISCE UN VALORE RANDOMICO HASH RIPORTANDOLO NELL' INTERVALLO DI VALORI INIZIO FINE
function randomHash(inizio,fine)
{
    diff=fine-inizio;
    return inizio+R.random_dec()*diff;
}

