//DISEGNA LA PEZZA DEL TESSUTO
function drawPezza(verticiPoly,
                    factor,
                    colorBack,
                    colorLineLight,
                    factorLineLight,
                    colorLineHard,
                    factorLineHard,
                    colorDirt,
                    factorDirt,
                    panel
                   )
{
  panel.noStroke();
  
  panel.fill(colorBack);
  
  //SFONDO COLORATO DELLA PEZZA
  panel.beginShape();
  for(let i=0;i<verticiPoly.length;i++)
    panel.vertex(verticiPoly[i].x,verticiPoly[i].y);
  panel.endShape(CLOSE);
  
  let min_x=w; max_x=0;
  let min_y=h; max_y=0;
  
  //trova x min e max
  for(let i=0;i<verticiPoly.length;i++)
  {  
     if(verticiPoly[i].x<min_x)
       min_x=verticiPoly[i].x;
     if(verticiPoly[i].x>max_x)
       max_x=verticiPoly[i].x;
    
     if(verticiPoly[i].y<min_y)
       min_y=verticiPoly[i].y;
     if(verticiPoly[i].y>max_y)
       max_y=verticiPoly[i].y;
  }
  

  
  //EFFETTO CHIARO
  panel.strokeWeight(1)
  panel.stroke(colorLineLight);
  f1=0.008 //randomHash(0.008,0.01)
  f2=randomHash(0.0001,0.005)
  for (var x = min_x/factor; x < max_x/factor; x++) { 
    for (var y = min_y/factor; y < max_y/factor; y++) {
        let x1=x*factor+(sin(noise_value(x,y,f1,f2,TWO_PI))*factor*factorLineLight)
        let y1=y*factor-(cos(noise_value(x,y,f1,f2,TWO_PI))*factor*factorLineLight)
        
        if(pointInside(x*factor,y*factor, verticiPoly))
          panel.line(x*factor,y*factor,x1,y1)
    }
  }
  
  
  //EFFETTO FILO/PELO DEL TESSUTO
  panel.stroke(colorLineHard)
  panel.strokeWeight(int(randomHash(1,3)))
  f1=randomHash(0.01,0.08);
  f2=randomHash(0.01,0.08);
    f3=randomHash(0.01,0.001);
  f4=randomHash(0.01,0.001);
  for (var x = min_x/factor; x < max_x/factor; x++) { 
    for (var y = min_y/factor; y < max_y/factor; y++) {
      //strokeWeight(int(randomHash(2,5)))
        let x1=x*factor+(sin(noise_value(x,y,f3,f4,factor))*noise_value(x,y,f1,f2,factor)*factorLineHard)
        let y1=y*factor-(cos(noise_value(x,y,f3,f4,factor))*noise_value(x,y,f1,f2,factor)*factorLineHard)
        
      if(pointInside(x*factor,y*factor, verticiPoly))
        panel.line(x*factor,y*factor,x1,y1)
    }
  }
  
  //EFFETTO SPORCO
  panel.noStroke();
  fDelta=randomHash(60,120)
  f1=randomHash(0.05,0.3)
  f2=randomHash(0.05,0.1)
  
  for(let x=min_x; x<max_x; x+=factor/2){
    for(let y=min_y; y<max_y; y+=factor/2){
      panel.fill([red(colorDirt),green(colorDirt),blue(colorDirt),noise(x*f1,y*f2)*fDelta])
       if(pointInside(x,y, verticiPoly))
         panel.circle(x+randomHash(-4,4),y+randomHash(-4,4),noise(x*0.002,y*0.002)*factorDirt)
        }
  }
  
}


function pointInside(x,y,vertici){
  
  var risp=false;
  var p=0;
  for(var k=0;k<vertici.length;k++)
  {
    if(p<vertici.length-1)
      p++;
    else 
      p=0;
    
     f_valuta=((vertici[p].x-vertici[k].x)*(y-vertici[k].y)/(vertici[p].y-vertici[k].y))+vertici[k].x;
    
    if((vertici[k].y>=y && vertici[p].y<y|| vertici[k].y<y && vertici[p].y>=y)) 
       if(x<f_valuta)
          risp=!risp;
  }
  return risp;

}

function noise_value(x,y,f1,f2,maxMap)
{ 
    return map(noise(x*f1, y*f2), 0, 1, 0, maxMap);
}


function drawRigaPoint(coord1, //COORDINATA PUNTO 1 
                        coord2, //COORDINATA PUNTO 2
                        densita, //DENSITA PUNTI RETTA (VALORE)
                        dim_minima, //DIMENSIONE MINIMA DEI PUNTI
                        dim_massima, //DIMENSIONE MASSIMA DEI PUNTI
                        rand_factor, //FATTORE RANDOM (INDICA DISTANZA MASSIMA DEI PUNTI RISPETTO ALLA RETTA TEORICA TRA COORD 1 e COORD 2. se impostato a zero significa nessun effetto randomico e tutti i punti sono allineati)
                        panel
                       )
{
  distXY=calcDistPunti(coord1.x,coord1.y,coord2.x,coord2.y);
  
  num_punti=distXY*densita;
  passoXY=distXY/num_punti;
  
  
  coordPoint=new VarCoord(0,0);
  for(let i=0;i<num_punti;i++)
  {
    calcPuntoRetta(coord1.x,coord1.y,coord2.x,coord2.y,passoXY*i,
                   coordPoint);
    panel.strokeWeight(randomHash(dim_minima,dim_massima))
    panel.point(coordPoint.x+randomHash(0,rand_factor),
          coordPoint.y+randomHash(0,rand_factor));
  }
  
}

//CALCOLA DISTANZA TRA DUE PUNTI
function calcDistPunti(x1,y1,x2,y2
    )
{
    return sqrt(pow(x2-x1,2)+pow(y2-y1,2));
}


//CALCOLA I PUNTI SU UNA RETTA AD UNA CERTA DISTANZA DAL PUNTO X1,y1
function calcPuntoRetta(x1,y1,x2,y2,
                        dist, //DISTANZA-RAGGIO DAL PUNTO DI RIFERIMENTO x1,y1
                        coord //COORDINATE PUNTO DISTANTE DA x1,Y1
    )
{
    let m;
    let q;
    let segno=1;
    x1=Math.trunc(x1);
    y1=Math.trunc(y1);
    x2=Math.trunc(x2);
    y2=Math.trunc(y2);
    

        if(y1==y2)
        {
            coord.x=x1+dist;
            coord.y=y1;
        }
        else
        {
            if(x1!=x2)
            {
                  m=(y1-y2)/(x1-x2);
                  q=((x2*y1)-(x1*y2))/(x2-x1);
              
                  if((m<0)&&(y1<y2))
                    segno=-1;

                  coord.x=((x1*sqrt(1+pow(m,2)))+dist*segno)/(sqrt(1+pow(m,2)));
                  coord.y=m*coord.x+q;

            }
            else
            {
                coord.x=x1;
                coord.y=y1+dist;
            }
    }

}


function calcPuntParalleli(x1,y1,x2,y2,
                        dist //DISTANZA-RAGGIO DAL PUNTO DI RIFERIMENTO               
    )
{
    let m,m_i;
    let q,q_i;
    let x,y;
    let segno;
    let coord=[]; //ARRAY OUTPUT
  
    x1=Math.trunc(x1);
    y1=Math.trunc(y1);
    x2=Math.trunc(x2);
    y2=Math.trunc(y2);

    coord[0]=new VarCoord(0,0);
    coord[1]=new VarCoord(0,0);
    coord[2]=new VarCoord(0,0);
    coord[3]=new VarCoord(0,0);
  
        x=x1;
        y=y1;
        segno=1;
  
        if(x1>x2)
            segno=-segno;

        //if(y1>y2)
          //  segno=-segno;

        if(x1!=x2)
        {
            m=(y1-y2)/(x1-x2);
            //q=y1-((y1-y2)/(x1-x2)*x1);
            q=((x2*y1)-(x1*y2))/(x2-x1);

            //CALCOLA IL VALORE DEL PUNTO MASSIMO CHE FUORIESCE DALLA LINEA IN BASE ALLO SPESSORE
            x=((x*sqrt(1+pow(m,2)))-segno*dist)/(sqrt(1+pow(m,2)));
            y=m*x+q

            //RETTA PERPENDICOLARE CHE PASSA PER IL PUNTO DI RIFERIMENTO( IN BASE AL TYPE)
            m_i=-1/m;
            q_i=y-(m_i*x);


            coord[0].x=((x*sqrt(1+pow(m_i,2)))-dist)/(sqrt(1+pow(m_i,2)));
            coord[0].y=m_i*coord[0].x+q_i;

            coord[1].x=((x*sqrt(1+pow(m_i,2)))+dist)/(sqrt(1+pow(m_i,2)));
            coord[1].y=m_i*coord[1].x+q_i;

        }
        
        //GESTISCI LINEE PERFETTAMENTE ORIZZONTALI E VERTICALI
        x=x1;
        y=y1;
        //PER LINEA ORIZZONTALE
        if((y1==y2)||(abs(y1-y2)<1))
        {

            coord[0].x=x-segno*dist;
            coord[0].y=y+dist;

            coord[1].x=x-segno*dist;
            coord[1].y=y-dist;

        }

        //PER LINEA VERTICALE
        if(x1==x2)
        {
          if(y1>y2)
            segno=-segno;
          coord[0].x=x+dist;
          coord[0].y=y-segno*dist;

          coord[1].x=x-dist;
          coord[1].y=y-segno*dist;
        }

        x=x2;
        y=y2;
        segno=-1;
  
        if(x1>x2)
            segno=-segno;
  
         //if(y1>y2)
           // segno=-segno;

        if(x1!=x2)
        {
            m=(y1-y2)/(x1-x2);
            //q=y1-((y1-y2)/(x1-x2)*x1);
            q=((x2*y1)-(x1*y2))/(x2-x1);

            //CALCOLA IL VALORE DEL PUNTO MASSIMO CHE FUORIESCE DALLA LINEA IN BASE ALLO SPESSORE
            x=((x*sqrt(1+pow(m,2)))-segno*dist)/(sqrt(1+pow(m,2)));
            y=m*x+q

            //RETTA PERPENDICOLARE CHE PASSA PER IL PUNTO DI RIFERIMENTO( IN BASE AL TYPE)
            m_i=-1/m;
            q_i=y-(m_i*x);


            coord[3].x=((x*sqrt(1+pow(m_i,2)))-dist)/(sqrt(1+pow(m_i,2)));
            coord[3].y=m_i*coord[3].x+q_i;

            coord[2].x=((x*sqrt(1+pow(m_i,2)))+dist)/(sqrt(1+pow(m_i,2)));
            coord[2].y=m_i*coord[2].x+q_i;

        }

        //GESTISCI LINEE PERFETTAMENTE ORIZZONTALI E VERTICALI
        x=x2;
        y=y2;
        //PER LINEA ORIZZONTALE
        if((y1==y2)||(abs(y1-y2)<1))
        {
            coord[3].x=x-segno*dist;
            coord[3].y=y+dist;

            coord[2].x=x-segno*dist;
            coord[2].y=y-dist;

        }
        //PER LINEA VERTICALE
        if(x1==x2)
        {
          coord[3].x=x+dist;
          coord[3].y=y-segno*dist;

          coord[2].x=x-dist;
          coord[2].y=y-segno*dist;
        }
  
      return coord;
  
}

function intersect_point(point1, point2, point3, point4) {
  coord=new VarCoord(0,0);
  
  const ua = ((point4.x- point3.x) * (point1.y - point3.y) - 
             (point4.y - point3.y) * (point1.x - point3.x)) /
            ((point4.y - point3.y) * (point2.x - point1.x) - 
             (point4.x - point3.x) * (point2.y - point1.y));
  
  const ub = ((point2.x - point1.x) * (point1.y - point3.y) - 
             (point2.y - point1.y) * (point1.x - point3.x)) /
            ((point4.y - point3.y) * (point2.x - point1.x) - 
             (point4.x - point3.x) * (point2.y - point1.y));
  
  coord.x = point1.x + ua * (point2.x - point1.x);
  coord.y = point1.y + ua * (point2.y- point1.y);
  
  return coord;
}


//FUNZIONE CHE RESTITUISCE UN ARRAY BIDIMENSIONALE DI COORDINATE RIPARTENDO LA SUPERFICIE IN UNA MATRICE
function matrixCoord(coord1,coord2,coord3,coord4,matrix)
{
   let coord_out; //OGGETTO COORDINATE
   let coordMatrix=[]; //MATRICE OUTPUT
  
   //INIZIALIZZA MATRICE
   for(let i=0;i<matrix+1;i++)
   { 
      coordMatrix[i]=[];
    }
  
   //DEFINISCI I PUNTI DELLA MATRICE SUL LATO ALTO
   let dist_12 = calcDistPunti(coord1.x,coord1.y,coord2.x,coord2.y);
   let passo_12 = dist_12/(matrix);
    for(let j=0;j<matrix+1;j++)
    { 
      coord_out=new VarCoord(0,0);
      calcPuntoRetta(coord1.x,coord1.y,coord2.x,coord2.y,(passo_12*j),coord_out);
      coordMatrix[0][j]=coord_out;

    }    

    //DEFINISCI I PUNTI DELLA MATRICE SUL LATO BASSO
    let dist_34 = calcDistPunti(coord3.x,coord3.y,coord4.x,coord4.y);
    let passo_34 = dist_34/(matrix);
    for(let j=0;j<matrix+1;j++)
    { 
       coord_out=new VarCoord(0,0);
       //coord4 sta prima di coord3 nel piano quindi passo è negativo
       calcPuntoRetta(coord4.x,coord4.y,coord3.x,coord3.y,(passo_34*j),coord_out);
       coordMatrix[matrix][j]=coord_out;
    }
   
   //DEFINISCI GLI ALTRI PUNTI DELLA MATRICE UNENDO I PUNTI SUL LATO ALTO CON QUELLI SUL LATO BASSO
   for(let j=0;j<matrix+1;j++) 
   {  
       
       let dist_x = calcDistPunti(coordMatrix[0][j].x,coordMatrix[0][j].y,
                                  coordMatrix[matrix][j].x,coordMatrix[matrix][j].y);
       let passo_x = dist_x/(matrix);
     
      for(let i=1;i<matrix;i++)
       { 
         coord_out=new VarCoord(0,0);
         //coord4 sta prima di coord3 nel piano quindi passo è negativo
         calcPuntoRetta(coordMatrix[0][j].x,coordMatrix[0][j].y,
                                  coordMatrix[matrix][j].x,coordMatrix[matrix][j].y,
                                  (passo_x*i),coord_out);
         
         coordMatrix[i][j]=coord_out;
       }
   }
   
   return coordMatrix;
  
}


//FUNZIONE CHE RESTITUISCE UN ARRAY BIDIMENSIONALE DI COORDINATE RIPARTENDO LA SUPERFICIE IN UNA MATRICE
function matrixCoordRand(coord1,coord2,coord3,coord4,matrix,maxRand)
{
   let coord_out; //OGGETTO COORDINATE
   let coordMatrix=[]; //MATRICE OUTPUT
  
   //INIZIALIZZA MATRICE
   for(let i=0;i<matrix+1;i++)
   { 
      coordMatrix[i]=[];
    }
  coordMatrix[0][0]=coord1;
  coordMatrix[0][matrix]=coord2;
  
   //DEFINISCI I PUNTI DELLA MATRICE SUL LATO ALTO
   let dist_12 = calcDistPunti(coord1.x,coord1.y,coord2.x,coord2.y);
   let passo_12 = dist_12/(matrix);
    for(let j=1;j<matrix;j++)
    { 
      coord_out=new VarCoord(0,0);
      coordMatrix[0][j]=new VarCoord(0,0);
      calcPuntoRetta(coord1.x,coord1.y,coord2.x,coord2.y,(passo_12*j),coord_out);
      coordMatrix[0][j].x=max(min(coord_out.x+randomHash(-maxRand,maxRand),coord2.x),coord1.x);
      if(j>0)
      coordMatrix[0][j].x=max(max(min(coord_out.x+randomHash(-maxRand,maxRand),coord2.x),coord1.x),coordMatrix[0][j-1].x);
      coordMatrix[0][j].y=coord_out.y;
    }    
    coordMatrix[matrix][0]=coord4;
  coordMatrix[matrix][matrix]=coord3;
  
    //DEFINISCI I PUNTI DELLA MATRICE SUL LATO BASSO
    let dist_34 = calcDistPunti(coord3.x,coord3.y,coord4.x,coord4.y);
    let passo_34 = dist_34/(matrix);
    for(let j=1;j<matrix;j++)
    { 
       coord_out=new VarCoord(0,0);
      coordMatrix[matrix][j]=new VarCoord(0,0);
       //coord4 sta prima di coord3 nel piano quindi passo è negativo
       calcPuntoRetta(coord4.x,coord4.y,coord3.x,coord3.y,(passo_34*j),coord_out);
       coordMatrix[matrix][j].x=max(min(coord_out.x+randomHash(-maxRand,maxRand),coord3.x),coord4.x);
       if(j>0)
       coordMatrix[matrix][j].x=max(max(min(coord_out.x+randomHash(-maxRand,maxRand),coord3.x),coord4.x),coordMatrix[matrix][j-1].x);
       coordMatrix[matrix][j].y=coord_out.y;
    }
      //DEFINISCI I PUNTI DELLA MATRICE SUL LATO SX
    let dist_14 = calcDistPunti(coord1.x,coord1.y,coord4.x,coord4.y);
    let passo_14 = dist_14/(matrix);
    for(let j=1;j<matrix;j++)
    { 
       coord_out=new VarCoord(0,0);
      coordMatrix[j][0]=new VarCoord(0,0);
       //coord4 sta prima di coord3 nel piano quindi passo è negativo
       calcPuntoRetta(coord1.x,coord1.y,coord4.x,coord4.y,(passo_14*j),coord_out);
       coordMatrix[j][0].x=coord_out.x;
       coordMatrix[j][0].y=max(min(coord_out.y+randomHash(-maxRand,maxRand),coord4.y),coord1.y);
       if(j>0)
       coordMatrix[j][0].y=max(max(min(coord_out.y+randomHash(-maxRand,maxRand),coord4.y),coord1.y),coordMatrix[j-1][0].y);
    }
  
        //DEFINISCI I PUNTI DELLA MATRICE SUL LATO DX
    let dist_23 = calcDistPunti(coord2.x,coord2.y,coord3.x,coord3.y);
    let passo_23 = dist_23/(matrix);
    for(let j=1;j<matrix;j++)
    { 
       coord_out=new VarCoord(0,0);
      coordMatrix[j][matrix]=new VarCoord(0,0);
       //coord4 sta prima di coord3 nel piano quindi passo è negativo
       calcPuntoRetta(coord2.x,coord2.y,coord3.x,coord3.y,(passo_23*j),coord_out);
       coordMatrix[j][matrix].x=coord_out.x;
       coordMatrix[j][matrix].y=max(min(coord_out.y+randomHash(-maxRand,maxRand),coord3.y),coord2.y);
       if(j>0)
       coordMatrix[j][matrix].y=max(max(min(coord_out.y+randomHash(-maxRand,maxRand),coord3.y),coord2.y),coordMatrix[j-1][matrix].y);
    }
  
    //DEFINISCI GLI ALTRI PUNTI DELLA MATRICE trovando le intersezioni tra i segmenti
   //orizzontali e quelli verticali
   for(let j=1;j<matrix;j++) 
   {  
       

      for(let i=1;i<matrix;i++)
       { 
         coord_out=intersect_point(coordMatrix[i][0],coordMatrix[i][matrix],
                                   coordMatrix[0][j],coordMatrix[matrix][j]);
         coordMatrix[i][j]=coord_out;
       }
   }
   
  
   //DEFINISCI GLI ALTRI PUNTI DELLA MATRICE UNENDO I PUNTI SUL LATO ALTO CON QUELLI SUL LATO BASSO
   for(let j=0;j<matrix+1;j++) 
   {  
       
       let dist_x = calcDistPunti(coordMatrix[0][j].x,coordMatrix[0][j].y,
                                  coordMatrix[matrix][j].x,coordMatrix[matrix][j].y);
       let passo_x = dist_x/(matrix);
     
      for(let i=1;i<matrix;i++)
       { 
         coord_out=new VarCoord(0,0);
         //coord4 sta prima di coord3 nel piano quindi passo è negativo
         calcPuntoRetta(coordMatrix[0][j].x,coordMatrix[0][j].y,
                                  coordMatrix[matrix][j].x,coordMatrix[matrix][j].y,
                                  (passo_x*i),coord_out);

         coordMatrix[i][j]=coord_out;
       }
   }
   
  
  
   return coordMatrix;
  
}



